func And(predicates ...predicate.Textbook) predicate.Textbook {
	return predicate.Textbook(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Textbook) predicate.Textbook {
	return predicate.Textbook(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Textbook) predicate.Textbook {
	return predicate.Textbook(sql.NotPredicates(p))
}
